import React from 'react';
import { DigoAsset } from '@digo-org/digo-api';
import { LineChart, Line, XAxis, YAxis, CartesianGrid, Tooltip, Legend, ResponsiveContainer } from 'recharts';

export class Asset extends DigoAsset {
  constructor() {
    super();
  }

  render() {
    // Global parameters
    const backgroundColor = this.globalParameters['background-color'] as string || '#ffffff';
    const showGrid = this.globalParameters['show-grid'] as boolean ?? true;
    const gridColor = this.globalParameters['grid-color'] as string || '#e5e7eb';
    const marginTop = this.globalParameters['margin-top'] as number || 20;
    const marginRight = this.globalParameters['margin-right'] as number || 30;
    const marginBottom = this.globalParameters['margin-bottom'] as number || 20;
    const marginLeft = this.globalParameters['margin-left'] as number || 40;

    // Line styling
    const solarColor = this.globalParameters['solar-color'] as string || '#d4af37';
    const windColor = this.globalParameters['wind-color'] as string || '#3b82f6';
    const hydroColor = this.globalParameters['hydro-color'] as string || '#10b981';
    const nuclearColor = this.globalParameters['nuclear-color'] as string || '#ef4444';
    const lineWidth = this.globalParameters['line-width'] as number || 2;
    const animationDuration = this.globalParameters['animation-duration'] as number || 1000;

    // Axis styling
    const showXAxis = this.globalParameters['show-x-axis'] as boolean ?? true;
    const showYAxis = this.globalParameters['show-y-axis'] as boolean ?? true;
    const xAxisLabel = this.globalParameters['x-axis-label'] as string || 'Year';
    const yAxisLabel = this.globalParameters['y-axis-label'] as string || 'Generation (TWh)';
    const axisLabelSize = this.globalParameters['axis-label-size'] as number || 14;
    const tickSize = this.globalParameters['tick-size'] as number || 12;

    // Legend styling
    const showLegend = this.globalParameters['show-legend'] as boolean ?? true;
    const legendPosition = this.globalParameters['legend-position'] as string || 'top';

    // Tooltip
    const showTooltip = this.globalParameters['show-tooltip'] as boolean ?? true;

    // Transform time series data into chart format
    // Get the array data from the first (and only) row
    const solarData = (this.instances?.[0]?.['solar-value'] as number[]) || [];
    const windData = (this.instances?.[0]?.['wind-value'] as number[]) || [];
    const hydroData = (this.instances?.[0]?.['hydro-value'] as number[]) || [];
    const nuclearData = (this.instances?.[0]?.['nuclear-value'] as number[]) || [];

    // Map each time point to its corresponding values
    const chartData = this.timeArray?.map((time, index) => ({
      time: time,
      solar: solarData[index] || 0,
      wind: windData[index] || 0,
      hydro: hydroData[index] || 0,
      nuclear: nuclearData[index] || 0,
    })) || [];

    return (
      <div
        style={{
          width: '100%',
          height: '100%',
          backgroundColor,
          padding: '20px',
          boxSizing: 'border-box',
        }}
      >
        <ResponsiveContainer width="100%" height="100%">
          <LineChart
            data={chartData}
            margin={{
              top: marginTop,
              right: marginRight,
              bottom: marginBottom,
              left: marginLeft,
            }}
          >
            {showGrid && (
              <CartesianGrid strokeDasharray="3 3" stroke={gridColor} />
            )}
            {showXAxis && (
              <XAxis
                dataKey="time"
                label={{
                  value: xAxisLabel,
                  position: 'insideBottom',
                  offset: -10,
                  style: { fontSize: axisLabelSize },
                }}
                tick={{ fontSize: tickSize }}
              />
            )}
            {showYAxis && (
              <YAxis
                label={{
                  value: yAxisLabel,
                  angle: -90,
                  position: 'insideLeft',
                  style: { fontSize: axisLabelSize },
                }}
                tick={{ fontSize: tickSize }}
              />
            )}
            {showTooltip && (
              <Tooltip
                contentStyle={{
                  backgroundColor: 'rgba(255, 255, 255, 0.95)',
                  border: '1px solid #ccc',
                  borderRadius: '4px',
                }}
                formatter={(value: number) => `${value.toFixed(2)} TWh`}
              />
            )}
            {showLegend && (
              <Legend
                verticalAlign={legendPosition as 'top' | 'middle' | 'bottom'}
                height={36}
                iconType="line"
              />
            )}
            <Line
              type="monotone"
              dataKey="solar"
              name="Solar"
              stroke={solarColor}
              strokeWidth={lineWidth}
              dot={{ r: 4 }}
              activeDot={{ r: 6 }}
              animationDuration={animationDuration}
            />
            <Line
              type="monotone"
              dataKey="wind"
              name="Wind"
              stroke={windColor}
              strokeWidth={lineWidth}
              dot={{ r: 4 }}
              activeDot={{ r: 6 }}
              animationDuration={animationDuration}
            />
            <Line
              type="monotone"
              dataKey="hydro"
              name="Hydropower"
              stroke={hydroColor}
              strokeWidth={lineWidth}
              dot={{ r: 4 }}
              activeDot={{ r: 6 }}
              animationDuration={animationDuration}
            />
            <Line
              type="monotone"
              dataKey="nuclear"
              name="Nuclear"
              stroke={nuclearColor}
              strokeWidth={lineWidth}
              dot={{ r: 4 }}
              activeDot={{ r: 6 }}
              animationDuration={animationDuration}
            />
          </LineChart>
        </ResponsiveContainer>
      </div>
    );
  }
}

